<?php
require_once __DIR__.'/../../config/cors.php';require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../helpers/response.php';require_once __DIR__.'/../../middleware/auth.php';
$actor=requireAuth($pdo);if($actor['role']!=='admin')sendError('Admin access required.',403);$method=$_SERVER['REQUEST_METHOD'];if($method!=='GET')requireCsrfToken();if($method==='GET'){$s=$pdo->query('SELECT role,permission_key AS permissionKey,allowed FROM role_permissions ORDER BY role,permission_key');$rows=$s->fetchAll();foreach($rows as &$r)$r['allowed']=(bool)$r['allowed'];sendResponse(['success'=>true,'data'=>$rows]);}$body=json_decode(file_get_contents('php://input'),true)?:[];$role=trim((string)($body['role']??''));$key=trim((string)($body['permissionKey']??''));if(!in_array($role,['admin','executive'],true)||$key==='')sendError('role and permissionKey are required.',422);$allowed=(bool)($body['allowed']??false);$s=$pdo->prepare('INSERT INTO role_permissions(role,permission_key,allowed) VALUES(:r,:k,:a) ON DUPLICATE KEY UPDATE allowed=VALUES(allowed)');$s->execute(['r'=>$role,'k'=>$key,'a'=>$allowed?1:0]);sendResponse(['success'=>true,'data'=>['role'=>$role,'permissionKey'=>$key,'allowed'=>$allowed]]);
